fn sqlite_snapshot_semio_object_typed_exact_subset_dialect_and_document_guard(){let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let snapshot=fixture();let database=project(&snapshot);let dialect=|v:&serde_json::Value|semio_framework_artifact_reference::ArtifactDialect{artifact_kind:v["artifactKind"].as_str().unwrap().into(),standard:v["standard"].as_str().unwrap().into(),subset:v["subset"].as_str().unwrap().into()};let mut callback=|_|true;let mut control=SqliteSnapshotControl::new(&mut callback,SqliteDatabaseLimits::default());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&database,&mut control).unwrap().diagnostics.is_empty());for invalid in f["invalidSqliteDialects"].as_array().unwrap(){assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(invalid),&database,&mut control).is_err());}let mut malformed=database;malformed.table_mut("semio_object_document").unwrap().rows[0].values[1]=SqliteValue::Text("other schema".into());assert!(snapshot.validate_sqlite_snapshot_subset(&dialect(&f["sqliteDialect"]),&malformed,&mut control).is_err());}

#[test]
fn sqlite_snapshot_semio_object_bounded_native_text_binary_admission() {
    let snapshot=fixture();let dialect=semio_framework_artifact_reference::ArtifactDialect{artifact_kind:"s.stdio.semio".into(),standard:"v1".into(),subset:"object".into()};
    let provider=<SemioObjectSnapshot as pack::snapshot::ArtifactPack>::sqlite_snapshot_codec().unwrap();
    for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{
        semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| snapshot.preflight_sqlite_snapshot_encoding(encoding,control)).unwrap();
        let database=semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|true, |control| snapshot.to_sqlite_database(control)).unwrap();
        let actual=semio_s_artifact_stdio_contract::testing::with_encoding(|native_owner| (provider.import)("Semio native admission",&dialect,&mut Some(database),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap().value;
        let expected=match encoding{SnapshotEncoding::Text=>store::io::IoPayload::Text(<SemioObjectSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&snapshot)),SnapshotEncoding::Binary=>store::io::IoPayload::Binary(<SemioObjectSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&snapshot))};assert!(actual==expected,"controlled native output differs from the authored ordinary wire");
        assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()}, &mut |_|true, |control| snapshot.preflight_sqlite_snapshot_encoding(encoding,control)).is_err());
        assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |_|false, |control| snapshot.preflight_sqlite_snapshot_encoding(encoding,control)).is_err());
    }
    let large= SemioObjectSnapshot{schema:"x".repeat(100000),..snapshot};
    assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()}, &mut |_|true, |control| large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Text,control)).is_err());
    assert!(semio_s_artifact_stdio_contract::testing::with_sqlite_recipient(SqliteDatabaseLimits::default(), &mut |p|p.phase!=SqliteSnapshotPhase::EncodeNative||p.completed==0, |control| large.preflight_sqlite_snapshot_encoding(SnapshotEncoding::Binary,control)).is_err());
}

