#[test]
fn sqlite_snapshot_semio_object_controlled_native_child_materialization(){
    let f:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap();let length=f["nativeChildBytes"].as_u64().unwrap() as usize;let cancel_bytes=f["nativeChildCancelBytes"].as_u64().unwrap() as usize;
    let mut snapshot=fixture();let mesh=snapshot.mesh.as_mut().unwrap();mesh.child_id="a".repeat(length);mesh.target.artifact_id=mesh.child_id.clone();
    for payload in [store::io::IoPayload::Binary(<SemioObjectSnapshot as pack::snapshot::ArtifactPack>::encode_pack(&snapshot)),store::io::IoPayload::Text(<SemioObjectSnapshot as pack::snapshot::ArtifactDsl>::print_dsl(&snapshot))]{
        let restored=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()), native_owner)).unwrap();
        assert_eq!(restored,snapshot);
        let mut canceled=false;
        let error=semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |event|{let cancel=event.phase==SqliteSnapshotPhase::DecodeNative&&event.total==length&&event.completed==cancel_bytes;canceled|=cancel;!cancel},SqliteDatabaseLimits::default()), native_owner)).unwrap_err();
        assert!(canceled&&error.message.contains("cancel"),"{error}");
        assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4096,..SqliteDatabaseLimits::default()}), native_owner)).is_err());
        assert!(semio_s_artifact_stdio_contract::testing::with_decoding(|native_owner| SemioObjectSnapshot::decode_sqlite_snapshot_native(&payload,&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default()), native_owner)).is_err());
    }
}

